import json, sqlite3, duckdb
from datetime import datetime, date
from collections import defaultdict

answers=json.load(open('answers.json'))
formats=['%d %b %Y, %H:%M','%B %d, %Y at %I:%M %p','%Y-%m-%d %H:%M:%S']
def parse_date(s):
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    raise ValueError(s)

con=duckdb.connect('query_dataset/indextrade_query.db', read_only=True, config={'extension_directory':'/workspace/.duckdb_extensions','memory_limit':'1GB'})
rows=con.execute('select "Index", "Date", "Open", "High", "Low", "Close", "CloseUSD" from index_trade').fetchall()
con.close()
parsed=[]
fail=[]
for row in rows:
    try:
        parsed.append((row[0], parse_date(row[1]), *row[2:]))
    except ValueError:
        fail.append(row[:2])
print('parse', len(rows), len(parsed), len(fail))
# Q1 independent
asia={'HSI','000001.SS','399001.SZ','N225','NSEI','TWII'}
vol=defaultdict(lambda: [0.0,0])
for idx,dt,op,hi,lo,cl,cusd in parsed:
    if idx in asia and dt >= date(2020,1,1) and op and hi is not None and lo is not None:
        vol[idx][0] += (hi-lo)/op
        vol[idx][1] += 1
q1_rank=sorted([(idx, s/n, n) for idx,(s,n) in vol.items()], key=lambda x: x[1], reverse=True)
print('q1', q1_rank)
# Q2
na={'NYA','IXIC','GSPTSE'}
updown=defaultdict(lambda: [0,0,0,0])
for idx,dt,op,hi,lo,cl,cusd in parsed:
    if idx in na and date(2018,1,1) <= dt < date(2019,1,1):
        updown[idx][0] += 1
        if cl > op: updown[idx][1]+=1
        elif cl < op: updown[idx][2]+=1
        else: updown[idx][3]+=1
q2=[idx for idx,v in sorted(updown.items()) if v[1]>v[2]]
print('q2', dict(sorted(updown.items())), q2)
# Q3
by_idx_month={}
last_price={}
for idx,dt,op,hi,lo,cl,cusd in parsed:
    if dt >= date(2000,1,1) and cusd is not None and cusd > 0:
        key=(idx, dt.year, dt.month)
        if key not in by_idx_month or dt > by_idx_month[key][0]:
            by_idx_month[key]=(dt,cusd)
        if idx not in last_price or dt > last_price[idx][0]:
            last_price[idx]=(dt,cusd)
shares=defaultdict(float); months=defaultdict(int); first={}; last={}
for (idx,y,m),(dt,price) in by_idx_month.items():
    shares[idx]+=1.0/price
    months[idx]+=1
    first[idx]=min(first.get(idx,dt),dt)
    last[idx]=max(last.get(idx,dt),dt)
q3_rank=[]
for idx in months:
    ret=shares[idx]*last_price[idx][1]/months[idx]-1
    q3_rank.append((idx, ret, months[idx], first[idx], last[idx]))
q3_rank.sort(key=lambda x: x[1], reverse=True)
print('q3', q3_rank)
print('answer checks', answers['q1']==q1_rank[0][0], answers['q2']=='; '.join(q2) or answers['q2']==q2[0], answers['q3'].split('; ')[0:5])
